import React, { useEffect, useState } from 'react';
import {
    Box, Typography, Container, Grid, Paper, Chip, Button, Link, Tabs, Tab, IconButton, Tooltip, useTheme
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Trans, useTranslation } from 'react-i18next';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CheckIcon from '@mui/icons-material/Check';
import ScheduleIcon from '@mui/icons-material/Schedule';
import NotificationsActiveIcon from '@mui/icons-material/NotificationsActive';
import EventIcon from '@mui/icons-material/Event';
import ExploreIcon from '@mui/icons-material/Explore';
import TuneIcon from '@mui/icons-material/Tune';
import TravelExploreIcon from '@mui/icons-material/TravelExplore';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import SmartToyOutlinedIcon from '@mui/icons-material/SmartToyOutlined';

// AI Agents (2026-09-30): connect AI assistants to the Muslim Companion MCP
// server (public, read-only prayer data). Every step here was tested against
// the live server before publishing.

const MCP_URL = 'https://alexa.imuslimlife.com/v1/mcp';

const TOOLS = [
    { icon: <ScheduleIcon />, name: 'get_prayer_times', key: 'prayer' },
    { icon: <NotificationsActiveIcon />, name: 'get_next_prayer', key: 'next' },
    { icon: <TravelExploreIcon />, name: 'find_location', key: 'find' },
    { icon: <EventIcon />, name: 'get_hijri_date', key: 'hijri' },
    { icon: <ExploreIcon />, name: 'get_qibla_direction', key: 'qibla' },
    { icon: <TuneIcon />, name: 'list_calculation_methods', key: 'methods' },
];

// Tab labels are product names (kept in English) except "Developers".
const SETUPS = [
    { label: 'Claude', key: 'claude', note: true, code: MCP_URL, code2: `claude mcp add --transport http muslim-companion ${MCP_URL}` },
    { label: 'ChatGPT', key: 'chatgpt', note: true, code: MCP_URL },
    { label: 'Gemini CLI', key: 'gemini', code: JSON.stringify({ mcpServers: { 'muslim-companion': { httpUrl: MCP_URL } } }, null, 2) },
    { label: 'Copilot / VS Code', key: 'vscode', code: JSON.stringify({ servers: { 'muslim-companion': { type: 'http', url: MCP_URL } } }, null, 2) },
    {
        labelKey: 'tabDevelopers', key: 'dev', note: true,
        code: `curl -s ${MCP_URL} \\\n  -H 'Content-Type: application/json' \\\n  -H 'Accept: application/json, text/event-stream' \\\n  -d '{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"get_prayer_times","arguments":{"latitude":43.6532,"longitude":-79.3832,"method":2}}}'`,
    },
];

const RICH = { b: <b />, i: <i />, a: <Link href="/llms.txt" /> };

function CodeBlock({ text }) {
    const { t } = useTranslation('aiAgents');
    const [copied, setCopied] = useState(false);
    const copy = () => {
        navigator.clipboard?.writeText(text).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1800); }).catch(() => {});
    };
    return (
        <Box dir="ltr" sx={{ position: 'relative', mt: 2, borderRadius: 2, bgcolor: '#0b1f1a', color: '#d1fae5', fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: { xs: '0.75rem', sm: '0.85rem' }, p: 2, pr: 6, whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
            {text}
            <Tooltip title={copied ? t('copied') : t('copy')}>
                <IconButton onClick={copy} size="small" aria-label={t('copy')} sx={{ position: 'absolute', top: 6, right: 6, color: '#a7f3d0' }}>
                    {copied ? <CheckIcon fontSize="small" /> : <ContentCopyIcon fontSize="small" />}
                </IconButton>
            </Tooltip>
        </Box>
    );
}

const AiAgentsPage = () => {
    const { t } = useTranslation('aiAgents');
    const theme = useTheme();
    const [tab, setTab] = useState(0);
    useEffect(() => { window.scrollTo(0, 0); }, []);
    const s = SETUPS[tab];

    return (
        <>
            <Helmet>
                <title>{t('meta.title')}</title>
                <meta name="description" content={t('meta.description')} />
                <meta property="og:title" content={t('meta.title')} />
                <meta property="og:description" content={t('meta.description')} />
                <meta name="twitter:title" content={t('meta.title')} />
                <meta name="twitter:description" content={t('meta.description')} />
            </Helmet>
            <Box sx={{ background: `linear-gradient(135deg, ${theme.palette.primary.main}, ${theme.palette.primary.dark})`, color: 'white', pt: 8, pb: 7 }}>
                <Container maxWidth="lg">
                    <Chip icon={<SmartToyOutlinedIcon sx={{ color: '#d1fae5 !important' }} />} label={t('chip')} sx={{ mb: 2, bgcolor: 'rgba(255,255,255,0.15)', color: '#d1fae5', fontWeight: 700 }} />
                    <Typography variant="h2" component="h1" fontWeight={600} gutterBottom sx={{ fontSize: { xs: '2.2rem', md: '3.2rem' } }}>
                        {t('h1')}
                    </Typography>
                    <Typography variant="h6" sx={{ opacity: 0.9, maxWidth: 760 }}>
                        {t('lede')}
                    </Typography>
                    <CodeBlock text={MCP_URL} />
                </Container>
            </Box>

            <Container maxWidth="lg" sx={{ py: 8 }}>
                <Typography variant="h3" component="h2" align="center" gutterBottom sx={{ fontSize: { xs: '1.8rem', md: '2.4rem' } }}>{t('toolsH2')}</Typography>
                <Typography align="center" color="text.secondary" sx={{ mb: 5, maxWidth: 720, mx: 'auto' }}>
                    {t('toolsSub')}
                </Typography>
                <Grid container spacing={3}>
                    {TOOLS.map((tool) => (
                        <Grid item xs={12} sm={6} md={4} key={tool.name}>
                            <Paper variant="outlined" sx={{ p: 3, height: '100%', borderRadius: 3 }}>
                                <Box sx={{ color: theme.palette.primary.main, mb: 1 }}>{tool.icon}</Box>
                                <Typography variant="h6">{t(`tools.${tool.key}.title`)}</Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>{t(`tools.${tool.key}.text`)}</Typography>
                                <Typography variant="caption" sx={{ fontFamily: 'monospace', opacity: 0.7, display: 'block', mt: 1 }}>{tool.name}</Typography>
                            </Paper>
                        </Grid>
                    ))}
                </Grid>
            </Container>

            <Box sx={{ bgcolor: theme.palette.background.paper, py: 8 }}>
                <Container maxWidth="md">
                    <Typography variant="h3" component="h2" align="center" gutterBottom sx={{ fontSize: { xs: '1.8rem', md: '2.4rem' } }}>{t('setupH2')}</Typography>
                    <Tabs value={tab} onChange={(_e, v) => setTab(v)} variant="scrollable" scrollButtons="auto" allowScrollButtonsMobile sx={{ mb: 3 }}>
                        {SETUPS.map((x) => <Tab key={x.key} label={x.labelKey ? t(x.labelKey) : x.label} />)}
                    </Tabs>
                    <Paper variant="outlined" sx={{ p: { xs: 2.5, sm: 4 }, borderRadius: 3 }}>
                        <Box component="ol" sx={{ paddingInlineStart: 3, m: 0, '& li': { mb: 1.5, lineHeight: 1.6 } }}>
                            {['s1', 's2', 's3'].map((k) => <li key={k}><Typography component="span"><Trans t={t} i18nKey={`${s.key}.${k}`} components={RICH} /></Typography></li>)}
                        </Box>
                        <CodeBlock text={s.code} />
                        {s.code2 && <CodeBlock text={s.code2} />}
                        {s.note && <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>{t(`${s.key}.note`)}</Typography>}
                    </Paper>
                    <Typography variant="body2" color="text.secondary" sx={{ mt: 3 }}>
                        <Trans t={t} i18nKey="tryAsk" components={RICH} />
                    </Typography>
                </Container>
            </Box>

            <Container maxWidth="md" sx={{ py: 8 }}>
                <Paper variant="outlined" sx={{ p: { xs: 3, sm: 4 }, borderRadius: 3, display: 'flex', gap: 2, alignItems: 'flex-start' }}>
                    <LockOutlinedIcon color="primary" sx={{ mt: 0.5 }} />
                    <Box>
                        <Typography variant="h6" gutterBottom>{t('privacyH')}</Typography>
                        <Typography color="text.secondary">
                            <Trans t={t} i18nKey="privacy" components={{ a: <Link href="/privacy-policy/" /> }} />
                        </Typography>
                    </Box>
                </Paper>
                <Box sx={{ textAlign: 'center', mt: 5 }}>
                    <Button variant="contained" component={RouterLink} to="/alexa-skill" sx={{ borderRadius: 8, px: 4 }}>{t('alexaCta')}</Button>
                </Box>
            </Container>
        </>
    );
};

export default AiAgentsPage;
